const CACHE='lotus-moba-v10';
const CORE=['./','./index.html','./style.css','./polish.css','./main.mjs','./engine.mjs','./lotus-game.mjs','./lotus-map.mjs','./lotus-layout.mjs','./lotus-scene.mjs','./spike.mjs','./clutch.mjs','./display.mjs','./tactics.mjs','./experience.mjs','./weapons.mjs','./renderer.mjs','./vfx.mjs','./audio.mjs','./controls.mjs','./joystick.mjs','./apple-touch-icon.png','./vendor/three.module.min.js','./vendor/three.core.min.js','./vendor/nipplejs.js','./icon.svg','./manifest.webmanifest','./audio/attack.ogg','./audio/hit.ogg','./audio/gate.ogg','./audio/break.ogg','./audio/zip.ogg','./guide.html','./assets/weapons/ares.png','./assets/weapons/bandit.png','./assets/weapons/bucky.png','./assets/weapons/bulldog.png','./assets/weapons/classic.png','./assets/weapons/frenzy.png','./assets/weapons/ghost.png','./assets/weapons/guardian.png','./assets/weapons/judge.png','./assets/weapons/marshal.png','./assets/weapons/odin.png','./assets/weapons/operator.png','./assets/weapons/outlaw.png','./assets/weapons/phantom.png','./assets/weapons/sheriff.png','./assets/weapons/shorty.png','./assets/weapons/spectre.png','./assets/weapons/stinger.png','./assets/weapons/tactical-knife.png','./assets/weapons/vandal.png','./assets/weapons/warden.png'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(CORE)));self.skipWaiting();});self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',event=>{if(event.request.method==='GET'&&new URL(event.request.url).origin===location.origin)event.respondWith(fetch(event.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(event.request,copy));}return r;}).catch(()=>caches.match(event.request,{ignoreSearch:true})));});
